/** A person on a sheet: a name and a grade (A, B or C). */
public record Person(long id, String sheetId, String name, String grade) {
}
package net.officefloor.hq.app.person;

/** A person add or edit with no name, an unknown grade, or no signed-in user. */
public class InvalidPersonException extends Exception {
    public InvalidPersonException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPerson {
    public void handle(@Parameter InvalidPersonException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.sheet;

import org.springframework.web.bind.annotation.PathVariable;

/** Fails when the sheet id has never been loaded. */
public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, SheetRepository repository)
            throws SheetNotFoundException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.exists(id)) {
            throw new SheetNotFoundException(id);
        }
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSheetLoad {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SheetRequest request,
            Out<SheetRequest> body) throws InvalidSheetException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (id.isEmpty() || id.length() > 100) {
            throw new InvalidSheetException("A sheet id is required (at most 100 characters).");
        }
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidSheetException("Sign in before loading a sheet.");
        }
        body.set(request);
    }
}

